fn synthetic_terminal_message(result: &Result<RunResult, RunError>) -> Option<String> {
    match result {
        Ok(_) => None,
        Err(RunError::Agent(err)) => Some(err.to_string()),
        Err(RunError::Cancelled) => Some(RunInterrupt::Cancelled.terminal_message().to_owned()),
